<svelte:options immutable={true} />

<script lang="ts">import { faFilter, faRedo, faSearch, faSortAmountDownAlt, faUndo } from '@fortawesome/free-solid-svg-icons';
import { faJSONEditorCollapse, faJSONEditorCompact, faJSONEditorExpand, faJSONEditorFormat } from '../../../../img/customFontawesomeIcons.js';
import Menu from '../../../controls/Menu.svelte';
export let readOnly = false;
export let onExpandAll;
export let onCollapseAll;
export let onFormat;
export let onCompact;
export let onSort;
export let onTransform;
export let onToggleSearch;
export let onUndo;
export let onRedo;
export let canExpandAll;
export let canCollapseAll;
export let canUndo;
export let canRedo;
export let canFormat;
export let canCompact;
export let canSort;
export let canTransform;
export let onRenderMenu;
let expandMenuItem;
$: expandMenuItem = {
    type: 'button',
    icon: faJSONEditorExpand,
    title: 'Expand all',
    className: 'jse-expand-all',
    onClick: onExpandAll,
    disabled: !canExpandAll
};
let collapseMenuItem;
$: collapseMenuItem = {
    type: 'button',
    icon: faJSONEditorCollapse,
    title: 'Collapse all',
    className: 'jse-collapse-all',
    onClick: onCollapseAll,
    disabled: !canCollapseAll
};
const searchItem = {
    type: 'button',
    icon: faSearch,
    title: 'Search (Ctrl+F)',
    className: 'jse-search',
    onClick: onToggleSearch
};
let defaultItems;
$: defaultItems = !readOnly
    ? [
        expandMenuItem,
        collapseMenuItem,
        {
            type: 'separator'
        },
        {
            type: 'button',
            icon: faJSONEditorFormat,
            title: 'Format JSON: add proper indentation and new lines (Ctrl+I)',
            className: 'jse-format',
            onClick: onFormat,
            disabled: readOnly || !canFormat
        },
        {
            type: 'button',
            icon: faJSONEditorCompact,
            title: 'Compact JSON: remove all white spacing and new lines (Ctrl+Shift+I)',
            className: 'jse-compact',
            onClick: onCompact,
            disabled: readOnly || !canCompact
        },
        {
            type: 'separator'
        },
        {
            type: 'button',
            icon: faSortAmountDownAlt,
            title: 'Sort',
            className: 'jse-sort',
            onClick: onSort,
            disabled: readOnly || !canSort
        },
        {
            type: 'button',
            icon: faFilter,
            title: 'Transform contents (filter, sort, project)',
            className: 'jse-transform',
            onClick: onTransform,
            disabled: readOnly || !canTransform
        },
        searchItem,
        {
            type: 'separator'
        },
        {
            type: 'button',
            icon: faUndo,
            title: 'Undo (Ctrl+Z)',
            className: 'jse-undo',
            onClick: onUndo,
            disabled: !canUndo
        },
        {
            type: 'button',
            icon: faRedo,
            title: 'Redo (Ctrl+Shift+Z)',
            className: 'jse-redo',
            onClick: onRedo,
            disabled: !canRedo
        },
        {
            type: 'space'
        }
    ]
    : [
        expandMenuItem,
        collapseMenuItem,
        {
            type: 'separator'
        },
        searchItem,
        {
            type: 'space'
        }
    ];
// eslint-disable-next-line svelte/no-unused-svelte-ignore
// svelte-ignore reactive_declaration_non_reactive_property
$: items = onRenderMenu(defaultItems) || defaultItems;
</script>

<Menu {items} />
